    protected override void OnMouseEnter(EventArgs e){hover=true;Invalidate();base.OnMouseEnter(e);}protected override void OnMouseLeave(EventArgs e){hover=pressed=false;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){pressed=true;Invalidate();base.OnMouseDown(e);}protected override void OnMouseUp(MouseEventArgs e){pressed=false;Invalidate();base.OnMouseUp(e);}protected override void OnEnabledChanged(EventArgs e){Invalidate();base.OnEnabledChanged(e);}
    protected override void OnPaint(PaintEventArgs e){Color background=pressed?Color.FromArgb(65,65,65):hover?Color.FromArgb(58,58,58):BackColor;bool primary=BackColor.B>100&&BackColor.R<45;if(primary)background=hover?Color.FromArgb(17,117,183):BackColor;e.Graphics.Clear(background);Color color=Enabled?ForeColor:Dark.Muted;var text=ClientRectangle;if(Glyph.Length>0){CodeIcons.Draw(e.Graphics,Glyph,new Rectangle(IconOnly?(Width-22)/2:7,(Height-22)/2,22,22),color,16);text.X=28;text.Width-=30;}if(!IconOnly)TextRenderer.DrawText(e.Graphics,Text,Font,text,color,TextFormatFlags.HorizontalCenter|TextFormatFlags.VerticalCenter|TextFormatFlags.EndEllipsis|TextFormatFlags.SingleLine|TextFormatFlags.NoPrefix);if(Focused&&ShowFocusCues)using(var pen=new Pen(Color.FromArgb(0,122,204)))e.Graphics.DrawRectangle(pen,1,1,Width-3,Height-3);}
