  internal class EditorForm:Form {
    readonly Panel content=new Panel(){Dock=DockStyle.Fill};readonly EditorCaption caption;bool resizable=true;
    public new Control.ControlCollection Controls{get{return content.Controls;}}
    public new Size ClientSize{get{return new Size(Math.Max(0,base.ClientSize.Width-2),Math.Max(0,base.ClientSize.Height-34));}set{base.ClientSize=new Size(value.Width+2,value.Height+34);}}
