    protected override CreateParams CreateParams{get{var value=base.CreateParams;if(resizable)value.Style|=0x40000;value.Style|=0x20000|0x10000;return value;}}
    protected override void OnHandleCreated(EventArgs e){base.OnHandleCreated(e);MaximizedBounds=Screen.FromHandle(Handle).WorkingArea;}
    protected override void OnPaint(PaintEventArgs e){base.OnPaint(e);using(var pen=new Pen(Dark.Border))e.Graphics.DrawRectangle(pen,0,0,Width-1,Height-1);}
    protected override void WndProc(ref Message message){if(message.Msg==0x83&&message.WParam!=IntPtr.Zero){message.Result=IntPtr.Zero;return;}base.WndProc(ref message);if(message.Msg==0x84&&resizable&&WindowState!=FormWindowState.Maximized){long point=message.LParam.ToInt64();var client=PointToClient(new Point((short)(point&0xffff),(short)((point>>16)&0xffff)));int x=client.X,y=client.Y;bool left=x<6,right=x>=Width-6,top=y<6,bottom=y>=Height-6;if(top&&left)message.Result=(IntPtr)13;else if(top&&right)message.Result=(IntPtr)14;else if(bottom&&left)message.Result=(IntPtr)16;else if(bottom&&right)message.Result=(IntPtr)17;else if(left)message.Result=(IntPtr)10;else if(right)message.Result=(IntPtr)11;else if(top)message.Result=(IntPtr)12;else if(bottom)message.Result=(IntPtr)15;}}
    sealed class EditorCaption:Control {
