      protected override void OnMouseMove(MouseEventArgs e){base.OnMouseMove(e);int next=e.X<Width-132?-1:Math.Min(2,(e.X-(Width-132))/44);if(next!=hover){hover=next;Invalidate();}}protected override void OnMouseLeave(EventArgs e){hover=-1;Invalidate();base.OnMouseLeave(e);}
