      protected override void OnDoubleClick(EventArgs e){base.OnDoubleClick(e);if(owner.MaximizeBox)owner.WindowState=owner.WindowState==FormWindowState.Maximized?FormWindowState.Normal:FormWindowState.Maximized;}
    }
  }
  internal sealed class EditorPage:Panel {public string Glyph="";public EditorPage(string text){Text=text;BackColor=Dark.Background;ForeColor=Dark.Foreground;}}
  internal sealed class EditorTabs:Control {
    readonly PageCollection pages;EditorPage selected;readonly List<Rectangle> headers=new List<Rectangle>();public Collection<EditorPage> TabPages{get{return pages;}}public int HeaderHeight=35;public EditorPage SelectedTab{get{return selected;}set{if(value==selected)return;selected=value;foreach(var page in pages)page.Visible=page==selected;PerformLayout();Invalidate();}}public int SelectedIndex{get{return pages.IndexOf(selected);}}
    public EditorTabs(){pages=new PageCollection(this);DoubleBuffered=true;BackColor=Dark.Background;Font=Dark.Font;}
    sealed class PageCollection:Collection<EditorPage>{readonly EditorTabs owner;public PageCollection(EditorTabs owner){this.owner=owner;}protected override void InsertItem(int index,EditorPage item){base.InsertItem(index,item);owner.Controls.Add(item);item.TextChanged+=(s,e)=>owner.Invalidate();item.Visible=false;if(owner.selected==null)owner.SelectedTab=item;owner.PerformLayout();owner.Invalidate();}}
    protected override void OnLayout(LayoutEventArgs e){base.OnLayout(e);foreach(var page in pages)page.SetBounds(0,HeaderHeight,Width,Math.Max(0,Height-HeaderHeight));}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(Dark.Panel);headers.Clear();int x=0;foreach(var page in pages){int width=Math.Max(100,TextRenderer.MeasureText(page.Text,Dark.Font).Width+47);var bounds=new Rectangle(x,0,width,HeaderHeight);headers.Add(bounds);bool active=page==selected;using(var brush=new SolidBrush(active?Dark.Background:Color.FromArgb(45,45,45)))e.Graphics.FillRectangle(brush,bounds);if(active)using(var brush=new SolidBrush(Color.FromArgb(0,122,204)))e.Graphics.FillRectangle(brush,x,0,width,1);using(var pen=new Pen(Color.FromArgb(37,37,38)))e.Graphics.DrawLine(pen,x+width-1,0,x+width-1,HeaderHeight);string glyph=page.Glyph.Length>0?page.Glyph:page.Text.Contains("合图")?"git-merge":page.Text.Contains("分支")?"git-branch":page.Text.Contains("锁")?"lock":page.Text.Contains("标签")?"tag":page.Text.Contains("暂存")?"archive":page.Text.Contains("CAD")?"diff":"files";CodeIcons.Draw(e.Graphics,glyph,new Rectangle(x+11,9,17,17),active?Dark.Foreground:Dark.Muted,16);TextRenderer.DrawText(e.Graphics,page.Text,Dark.Font,new Rectangle(x+32,0,width-35,HeaderHeight),active?Dark.Foreground:Dark.Muted,TextFormatFlags.Left|TextFormatFlags.VerticalCenter);x+=width;}}
    protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);for(int i=0;i<headers.Count;i++)if(headers[i].Contains(e.Location)){SelectedTab=pages[i];break;}}
  }
  internal sealed class ActivityRail:Control {
    readonly string[] icons={"files","source-control","graph","git-merge"};readonly string[] labels={"工作副本","源代码管理","Git Graph","人工合图"};readonly ToolTip tooltip=new ToolTip();int hover=-1;public int Active=2;public event Action<int> Activated;
    public ActivityRail(){Width=48;BackColor=Color.FromArgb(51,51,51);DoubleBuffered=true;Cursor=Cursors.Hand;}
    protected override void OnPaint(PaintEventArgs e){e.Graphics.Clear(BackColor);for(int i=0;i<icons.Length;i++){if(i==Active)using(var brush=new SolidBrush(Dark.Foreground))e.Graphics.FillRectangle(brush,0,i*48+5,2,38);CodeIcons.Draw(e.Graphics,icons[i],new Rectangle(11,i*48+12,26,26),i==Active||i==hover?Dark.Foreground:Color.FromArgb(147,147,147),25);}CodeIcons.Draw(e.Graphics,"settings-gear",new Rectangle(11,Height-40,26,26),Dark.Muted,24);}
    protected override void OnMouseMove(MouseEventArgs e){int next=e.Y/48;if(next!=hover){hover=next;tooltip.SetToolTip(this,next>=0&&next<labels.Length?labels[next]:"设置");Invalidate();}base.OnMouseMove(e);}protected override void OnMouseLeave(EventArgs e){hover=-1;Invalidate();base.OnMouseLeave(e);}protected override void OnMouseDown(MouseEventArgs e){base.OnMouseDown(e);int index=e.Y>Height-48?4:e.Y/48;if(Activated!=null)Activated(index);}
    protected override void Dispose(bool disposing){if(disposing)tooltip.Dispose();base.Dispose(disposing);}
  }
